        for y in range(H, -1, -1):
            if not blk(x, y):
                continue
            v = 1
            if blk(x + 1, y):
                v += f[x + 1][y]
            if blk(x, y + 1):
                v += f[x][y + 1]
            v %= MOD
            f[x][y] = v
            total += v
    print(total % MOD)
